const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:12px;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden;background:transparent}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;border:0;background:none;padding:0;margin:0;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.card button:disabled{cursor:default}\n.card[data-size=\"3x3\"]{padding:9px;font-size:12px}\n.home,.page{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\n.card[data-size=\"3x3\"] .home,.card[data-size=\"3x3\"] .page{gap:6px}\n\n.top{flex:none;display:flex;align-items:center;gap:8px;min-width:0}\n.ttl{flex:1;min-width:0;display:flex;flex-direction:column}\n.h{font-weight:750;font-size:16px;letter-spacing:.02em;white-space:nowrap}\n.s{color:var(--muted);font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.num{display:none}\n.stats{display:none}\n.add{flex:none;height:34px;min-width:34px;padding:0 11px;border-radius:17px;background:var(--accent);color:var(--on-accent);font-size:18px;font-weight:700;line-height:1;display:flex;align-items:center;justify-content:center}\n.add span{display:none;font-size:12.5px;margin-left:5px}\n.card:not([data-size=\"3x3\"]) .add span{display:inline}\n\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin}\n.row{flex:none;display:flex;align-items:center;gap:8px;min-width:0;background:var(--panel-paper);border:1px solid var(--line);border-radius:12px;padding:8px 8px 8px 11px}\n.row[data-st=\"over\"]{border-color:var(--accent);box-shadow:inset 3px 0 0 var(--accent)}\n.row[data-st=\"today\"],.row[data-st=\"new\"]{box-shadow:inset 3px 0 0 var(--accent-alt)}\n.rmain{flex:1;min-width:0;cursor:pointer;outline-offset:2px}\n.name{font-weight:650;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.meta{display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;margin-top:3px;min-width:0}\n.badge{font-size:11px;font-weight:650;line-height:1.5;padding:0 7px;border-radius:9px;white-space:nowrap;color:var(--muted);border:1px solid var(--line)}\n.row[data-st=\"over\"] .badge,.hero[data-st=\"over\"] .badge{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.row[data-st=\"today\"] .badge,.row[data-st=\"new\"] .badge,.hero[data-st=\"today\"] .badge,.hero[data-st=\"new\"] .badge{background:var(--soft);border-color:var(--accent);color:var(--ink)}\n.row[data-st=\"soon\"] .badge,.hero[data-st=\"soon\"] .badge{background:var(--soft);color:var(--ink)}\n.nx{font-size:11.5px;font-weight:600;color:var(--ink);white-space:nowrap;font-variant-numeric:tabular-nums}\n.wk{display:none}\n.sub{display:none;margin-top:3px;font-size:11.5px;color:var(--muted);overflow-wrap:anywhere;font-variant-numeric:tabular-nums}\n.bar{height:3px;border-radius:2px;background:var(--line);margin-top:6px;overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:2px}\n.row[data-st=\"later\"] .bar i,.row[data-st=\"soon\"] .bar i{background:var(--accent-alt)}\n.done{flex:none;min-width:38px;height:38px;border-radius:19px;padding:0 10px;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;gap:5px;font-weight:700}\n.done b{font-size:16px;line-height:1}\n.done span{display:none;font-size:12.5px;white-space:nowrap}\n.row[data-st=\"later\"] .done,.row[data-st=\"soon\"] .done{background:var(--soft);color:var(--ink);box-shadow:inset 0 0 0 1px var(--line)}\n.done:disabled,.row .done:disabled{background:transparent;color:var(--muted);box-shadow:inset 0 0 0 1px var(--line)}\n.card[data-size=\"6x3\"] .done,.card[data-size=\"6x6\"] .done{padding:0 14px}\n.card[data-size=\"6x3\"] .done span,.card[data-size=\"6x6\"] .done span{display:inline}\n\n.undo{flex:none;display:flex;align-items:center;gap:8px;min-height:30px;padding:2px 4px 2px 10px;border-radius:15px;background:var(--soft);color:var(--ink);font-size:12px}\n.undo span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.undo button{flex:none;height:26px;padding:0 10px;border-radius:13px;background:var(--panel-paper);color:var(--ink);font-weight:650;box-shadow:inset 0 0 0 1px var(--line)}\n.err{flex:none;font-size:12px;padding:5px 9px;border-radius:9px;border:1px solid var(--accent);background:var(--soft);color:var(--ink)}\n\n.empty{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:6px}\n.empty p{margin:0}\n.e1{font-weight:700;font-size:15px}\n.e2{color:var(--muted);font-size:12px;line-height:1.5}\n.card[data-size=\"3x3\"] .e2{display:none}\n.pri{height:36px;padding:0 16px;border-radius:18px;background:var(--accent);color:var(--on-accent);font-weight:700}\n\n\n/* form & detail */\n.hd{flex:none;display:flex;align-items:center;gap:8px;min-width:0}\n.back{flex:none;width:34px;height:34px;border-radius:17px;background:var(--soft);color:var(--ink);font-size:20px;line-height:1;box-shadow:inset 0 0 0 1px var(--line)}\n.pt{flex:1;min-width:0;font-weight:700;font-size:15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.hbtn{flex:none;height:34px;padding:0 13px;border-radius:17px;background:var(--accent);color:var(--on-accent);font-weight:700;font-size:13px;white-space:nowrap}\n.hbtn.ghost{background:var(--soft);color:var(--ink);box-shadow:inset 0 0 0 1px var(--line)}\n.hbtn:disabled{opacity:.6}\n.pbody{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:12px;padding:2px 2px 4px 0;scrollbar-width:thin}\n.col{display:flex;flex-direction:column;gap:10px;min-width:0}\n.fld{display:flex;flex-direction:column;gap:5px;min-width:0}\n.lbl{font-size:11.5px;color:var(--muted);font-weight:650}\n.hint{font-size:11.5px;color:var(--muted)}\n.in{width:100%;min-width:0;height:38px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font:inherit;font-size:14px}\n.in:focus{outline:2px solid var(--accent);outline-offset:1px}\n.ivr{display:flex;gap:8px;align-items:center;min-width:0}\n.num-in{flex:none;width:76px;text-align:center}\n.seg{flex:1;min-width:0;display:flex;border:1px solid var(--line);border-radius:10px;overflow:hidden;height:38px}\n.seg button{flex:1;min-width:0;background:var(--panel-paper);color:var(--ink);font-size:14px}\n.seg button+button{border-left:1px solid var(--line)}\n.seg button[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);font-weight:700}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{height:30px;padding:0 12px;border-radius:15px;background:var(--soft);color:var(--ink);font-size:12.5px;box-shadow:inset 0 0 0 1px var(--line)}\n\n.hero{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:10px 12px;border-radius:14px;background:var(--panel-paper);border:1px solid var(--line)}\n.hero[data-st=\"over\"]{border-color:var(--accent)}\n.hero .k{font-size:11.5px;color:var(--muted);font-weight:650}\n.hero .v{font-size:20px;font-weight:750;line-height:1.25;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.card[data-size=\"3x3\"] .hero .v{font-size:17px}\n.facts{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 12px;font-size:12.5px;font-variant-numeric:tabular-nums}\n.facts span{min-width:0;overflow-wrap:anywhere}\n.fk{color:var(--muted)}\n.bigdone{height:42px;border-radius:21px;background:var(--accent);color:var(--on-accent);font-weight:700;font-size:14px;padding:0 14px;width:100%}\n.bigdone:disabled{background:transparent;color:var(--muted);box-shadow:inset 0 0 0 1px var(--line)}\n.bfr{display:flex;gap:8px;align-items:center;min-width:0}\n.sec{flex:none;height:38px;padding:0 14px;border-radius:10px;background:var(--soft);color:var(--ink);font-weight:650;box-shadow:inset 0 0 0 1px var(--line)}\n.hist{display:flex;flex-direction:column;gap:5px}\n.hi{display:flex;align-items:center;gap:8px;min-height:36px;padding:3px 4px 3px 10px;border-radius:10px;background:var(--panel-paper);border:1px solid var(--line)}\n.ht{flex:1;min-width:0;font-size:12.5px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.hi button{flex:none;width:30px;height:30px;border-radius:15px;background:var(--soft);color:var(--ink);font-size:16px;line-height:1}\n.del{height:36px;border-radius:18px;background:transparent;color:var(--muted);box-shadow:inset 0 0 0 1px var(--line);font-size:12.5px}\n.cfm{display:flex;flex-direction:column;gap:8px;padding:10px;border-radius:12px;background:var(--soft);border:1px solid var(--accent);font-size:12.5px;overflow-wrap:anywhere}\n.cfr{display:flex;gap:8px;flex-wrap:wrap}\n\n/* 3x6 tall narrow */\n.card[data-size=\"3x6\"] .sub{display:block}\n.card[data-size=\"3x6\"] .row{padding-top:10px;padding-bottom:10px}\n\n/* 6x3 wide short: summary rail + list */\n.card[data-size=\"6x3\"] .home{display:grid;grid-template-columns:104px minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;column-gap:12px;row-gap:6px}\n.card[data-size=\"6x3\"] .top{grid-column:1;grid-row:1;flex-direction:column;align-items:stretch;justify-content:space-between;gap:6px}\n.card[data-size=\"6x3\"] .ttl .s{display:none}\n.card[data-size=\"6x3\"] .num{display:flex;flex-direction:column;align-items:flex-start;line-height:1}\n.card[data-size=\"6x3\"] .num b{font-size:44px;font-weight:800;font-variant-numeric:tabular-nums;color:var(--accent)}\n.card[data-size=\"6x3\"] .num i{font-style:normal;font-size:12px;color:var(--muted);margin-top:2px}\n.card[data-size=\"6x3\"] .list,.card[data-size=\"6x3\"] .empty{grid-column:2;grid-row:1}\n.card[data-size=\"6x3\"] .err,.card[data-size=\"6x3\"] .undo{grid-column:1 / -1;grid-row:2}\n.card[data-size=\"6x3\"] .sub{display:block}\n.card[data-size=\"6x3\"] .wk{display:inline}\n.card[data-size=\"6x3\"] .pbody{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-content:start;align-items:start}\n\n/* 6x6 large */\n.card[data-size=\"6x6\"]{padding:16px}\n.card[data-size=\"6x6\"] .home,.card[data-size=\"6x6\"] .page{gap:12px}\n.card[data-size=\"6x6\"] .h{font-size:19px}\n.card[data-size=\"6x6\"] .s{font-size:12.5px}\n.card[data-size=\"6x6\"] .stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;flex:none}\n.card[data-size=\"6x6\"] .stats div{display:flex;flex-direction:column;gap:2px;padding:8px 10px;border-radius:12px;background:var(--panel-paper);border:1px solid var(--line)}\n.card[data-size=\"6x6\"] .stats b{font-size:24px;line-height:1.1;font-weight:800;font-variant-numeric:tabular-nums}\n.card[data-size=\"6x6\"] .stats span{font-size:11.5px;color:var(--muted)}\n.card[data-size=\"6x6\"] .row{padding:11px 11px 11px 14px;gap:10px}\n.card[data-size=\"6x6\"] .name{font-size:15px}\n.card[data-size=\"6x6\"] .sub{display:block}\n.card[data-size=\"6x6\"] .wk{display:inline}\n.card[data-size=\"6x6\"] .bar{margin-top:8px}\n";
const UNIT_TXT={day:'天',week:'周',month:'个月'};
const WK='日一二三四五六';
function ut(s){const p=s.split('-');return Date.UTC(+p[0],+p[1]-1,+p[2]);}
function pd(s){const p=s.split('-');return new Date(+p[0],+p[1]-1,+p[2]);}
function fd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function dd(a,b){return Math.round((ut(b)-ut(a))/864e5);}
function addIv(s,n,u){
  const d=pd(s);
  if(u==='month'){
    const day=d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth()+n);
    const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();
    d.setDate(Math.min(day,last));
  }else{
    d.setDate(d.getDate()+(u==='week'?7*n:n));
  }
  return fd(d);
}
function fmt(s,today){
  const d=pd(s);
  const y=today&&s.slice(0,4)!==today.slice(0,4)?d.getFullYear()+'年':'';
  return y+(d.getMonth()+1)+'月'+d.getDate()+'日';
}
function wkOf(s){return '周'+WK[pd(s).getDay()];}
function ivText(c){return '每 '+c.every+' '+(UNIT_TXT[c.unit]||'天');}
function nowT(){
  const n=new Date();
  return String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');
}
function cmpH(a,b){
  if(a.d!==b.d)return a.d<b.d?1:-1;
  return (b.at||0)-(a.at||0);
}
function histOf(c){return (Array.isArray(c.history)?c.history:[]).slice().sort(cmpH);}
function info(c,today){
  const every=Math.max(1,Number(c.every)||1);
  const cc=c.every===every?c:{...c,every};
  const last=histOf(cc)[0]||null;
  if(!last){
    return {c:cc,last:null,next:null,delta:0,st:'new',label:'还没做过',pct:0};
  }
  const next=addIv(last.d,every,cc.unit);
  const delta=dd(today,next);
  const total=Math.max(1,dd(last.d,next));
  const spent=dd(last.d,today);
  const pct=Math.max(0,Math.min(100,Math.round(spent/total*100)));
  let st,label;
  if(delta<0){st='over';label='已逾期 '+(-delta)+' 天';}
  else if(delta===0){st='today';label='今天到期';}
  else if(delta===1){st='soon';label='明天';}
  else if(delta<=3){st='soon';label=delta+' 天后';}
  else{st='later';label=delta+' 天后';}
  return {c:cc,last,next,delta,st,label,pct};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const today=day();
  const chores=Array.isArray(state&&state.chores)?state.chores:[];
  const infos=chores.map(c=>info(c,today)).sort((a,b)=>a.delta-b.delta||(a.c.createdAt||0)-(b.c.createdAt||0));
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat().filter(k=>k!=null&&k!==false));
  const scOf=()=>ui.sc||(ui.sc={});

  function go(view,extra){
    ui.view=view;
    ui.err='';
    ui.undo=null;
    ui.confirmDel=false;
    ui.bf=null;
    ui.saving=false;
    if(view!=='list')scOf()[view]=0;
    Object.assign(ui,extra||{});
    redraw();
  }
  function fail(msg){ui.err=msg;redraw();}
  function patch(fn,onFail){
    return update(s=>({...s,chores:fn(Array.isArray(s&&s.chores)?s.chores:[])})).catch(()=>{
      if(onFail)onFail();
      ui.err='保存失败，请重试';
      redraw();
    });
  }
  function complete(c){
    if(ui.busy)return;
    ui.busy=true;
    ui.err='';
    const hid=uid(),d=day(),t=nowT();
    if(ui.view!=='detail')ui.undo={cid:c.id,hid,name:c.name};
    patch(list=>list.map(x=>x.id===c.id?{...x,history:[...(Array.isArray(x.history)?x.history:[]),{id:hid,d,t,at:Date.now()}]}:x),()=>{ui.undo=null;})
      .then(()=>{ui.busy=false;});
  }
  function undo(){
    const u=ui.undo;
    if(!u)return;
    ui.undo=null;
    patch(list=>list.map(x=>x.id===u.cid?{...x,history:(Array.isArray(x.history)?x.history:[]).filter(e=>e.id!==u.hid)}:x));
  }

  function rowView(x){
    const c=x.c;
    const doneToday=!!(x.last&&x.last.d===today);
    const bar=x.last?h('div',{class:'bar'},h('i',{})):null;
    if(bar)bar.firstChild.style.width=x.pct+'%';
    const open=()=>go('detail',{cid:c.id});
    return h('div',{class:'row','data-st':x.st},
      h('div',{class:'rmain',role:'button',tabindex:'0','aria-label':'查看 '+c.name,onclick:open,onkeydown:e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}}},
        h('div',{class:'name'},c.name),
        h('div',{class:'meta'},
          h('span',{class:'badge'},x.label),
          h('span',{class:'nx'},x.next?['下次 ',fmt(x.next,today),h('span',{class:'wk'},' '+wkOf(x.next))]:'完成后显示下次')),
        h('div',{class:'sub'},ivText(c)+' · '+(x.last?'上次 '+fmt(x.last.d,today)+(x.last.t?' '+x.last.t:''):'暂无记录')),
        bar),
      h('button',{type:'button',class:'done',disabled:doneToday,'aria-label':(doneToday?'今日已完成 ':'完成 ')+c.name,onclick:()=>complete(c)},
        h('b',{},'✓'),h('span',{},doneToday?'今日已做':'完成')));
  }

  function listView(){
    const dueN=infos.filter(x=>x.st==='over'||x.st==='today'||x.st==='new').length;
    const overN=infos.filter(x=>x.st==='over').length;
    const weekN=infos.filter(x=>x.delta>=1&&x.delta<=7&&x.st!=='new').length;
    const nextUp=infos.find(x=>x.next&&x.delta>0);
    let sum;
    if(!chores.length)sum='点右侧 + 添加第一项';
    else if(dueN)sum=dueN+' 项待做';
    else sum='都按时'+(nextUp?' · 最近 '+fmt(nextUp.next,today):'');
    const openAdd=()=>go('form',{editId:null,draft:{name:'',every:'',unit:'day',last:''}});
    const addBtn=h('button',{type:'button',class:'add','aria-label':'添加家务',onclick:openAdd},'+',h('span',{},'添加'));
    const top=h('div',{class:'top'},
      h('div',{class:'ttl'},h('span',{class:'h'},'家务记录'),h('span',{class:'s'},sum)),
      chores.length?h('div',{class:'num','aria-hidden':'true'},h('b',{},String(dueN)),h('i',{},'项待做')):null,
      addBtn);
    const stats=chores.length?h('div',{class:'stats'},
      h('div',{},h('b',{},String(overN)),h('span',{},'已逾期')),
      h('div',{},h('b',{},String(dueN-overN)),h('span',{},'今天待做')),
      h('div',{},h('b',{},String(weekN)),h('span',{},'7 天内到期'))):null;
    let body;
    if(!chores.length){
      body=h('div',{class:'empty'},
        h('p',{class:'e1'},'还没有家务'),
        h('p',{class:'e2'},'添加后设好多久做一次；点「完成」会记下当时的时间，并算出下次该做的日期。'),
        h('button',{type:'button',class:'pri',onclick:openAdd},'添加家务'));
    }else{
      body=h('div',{class:'list',onscroll:e=>{scOf().list=e.target.scrollTop;}},infos.map(rowView));
    }
    return h('div',{class:'home'},
      top,stats,
      ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null,
      body,
      ui.undo?h('div',{class:'undo'},h('span',{},'已记录「'+ui.undo.name+'」'),h('button',{type:'button',onclick:undo},'撤销')):null);
  }


  function formView(){
    const editId=ui.editId||null;
    const d=ui.draft||(ui.draft={name:'',every:'',unit:'day',last:''});
    const back=()=>editId?go('detail',{cid:editId}):go('list');
    function save(){
      if(ui.saving)return;
      const name=String(d.name||'').trim();
      const n=Number(d.every);
      if(!name)return fail('请填写家务名称');
      if(String(d.every).trim()===''||!Number.isInteger(n)||n<1||n>999)return fail('间隔请填 1 到 999 的整数');
      if(!editId&&d.last&&d.last>today)return fail('上次完成日期不能晚于今天');
      const dup=chores.some(c=>c.id!==editId&&String(c.name).trim().toLowerCase()===name.toLowerCase());
      if(dup)return fail('已经有同名的家务了');
      const unit=UNIT_TXT[d.unit]?d.unit:'day';
      const id=uid(),hid=uid(),last=d.last||'';
      ui.saving=true;
      ui.err='';
      redraw();
